    width: '2em',
    marginRight: '1em',
    textAlign: 'right',
    color: 'hsl(var(--muted-foreground, 220 9% 46%) / 0.5)',
  },

  // ========== Syntax Highlighting (GitHub-like) ==========
  '.hljs-keyword': { color: '#d73a49' },
