        doc: 'Hello world',
        extensions: [editorTheme],
      });

      const container = document.createElement('div');
      const view = new EditorView({ state, parent: container });

      view.dispatch({
        selection: { anchor: 5 },
      });

      expect(view.state.selection.main.anchor).toBe(5);

      view.destroy();
    });
  });
});

